const $=id=>document.getElementById(id),e=(tag,text)=>{const n=document.createElement(tag);if(text!=null)n.textContent=text;return n},format=v=>v==null?'—':Number(v).toLocaleString('zh-CN'),time=t=>t?new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+' UTC+8':'—';let page=0,busy=false;
const types={watch:'今日关注',top:'每日 Top 5',daily:'每日资讯',stock:'美股图文',spot:'现货上新',perp:'永续合约上新',legacy:'旧记录迁移'};
const states={published:'已发布',pending:'等待确认',scheduled:'已定时',withdrawn:'已撤回',submitting:'提交中／待核对',unknown:'提交结果待核对',failed:'失败',partial:'部分成功',withdrawing:'撤回中'};
async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const d=await r.json();if(!r.ok)throw Error(d.error??'读取失败');return d}
function controls(value){busy=value;for(const id of ['history-refresh','history-import','history-account','history-prev','history-next'])$(id).disabled=value}
async function load(){const d=await api('/api/history?'+new URLSearchParams({locale:$('history-account').value,page}));$('history-rows').replaceChildren();const eligible=d.rows.filter(r=>r.metrics&&Date.parse(r.published_at)<=Date.now()-86400000);const totals=e('div');totals.className='history-kpis';for(const [label,value]of [['此账号发布记录',d.total],['本页有统计的帖子',eligible.length],['本页累计曝光 / 浏览',eligible.some(r=>r.metrics.reach!=null)?eligible.reduce((n,r)=>n+(r.metrics.reach??0),0):null],['本页累计互动',eligible.some(r=>r.metrics.engagement!=null)?eligible.reduce((n,r)=>n+(r.metrics.engagement??0),0):null]]){const card=e('div');card.append(e('span',label),e('strong',format(value)));totals.append(card)}$('history-summary').replaceChildren(totals,e('p','“—”表示 Publer 未提供；汇总仅计本页有值的帖子，各帖子采集时间可能不同。互动沿用 Publer 口径：点赞、回复、转发与帖子点击。'));
 for(const r of d.rows){const card=e('article');card.className='history-card';card.append(e('h3',(types[r.content_type]??r.content_type)+' · '+(states[r.state]??r.state)),e('p','发布：'+time(r.published_at??r.scheduled_at)+' · 记录创建：'+time(r.created_at)));if(r.thumbnail){const image=e('img');image.src=r.thumbnail;image.alt='已发布配图';image.loading='lazy';card.append(image)}card.append(e('pre',r.caption));if(r.post_url){const a=e('a','查看 X 原帖 ↗');a.href=r.post_url;a.target='_blank';a.rel='noopener noreferrer';card.append(a)}const mature=r.published_at&&Date.parse(r.published_at)<=Date.now()-86400000;
 if(r.state==='scheduled')card.append(e('p','已排期，实际发布后开始计算 24h。'));
 else if(!r.published_at)card.append(e('p','等待确认实际发布时间。'));
 else if(!mature)card.append(e('p','待满 24h · 可统计时间：'+time(new Date(Date.parse(r.published_at)+86400000).toISOString())));
 else if(!r.metrics)card.append(e('p',r.metrics_error??'满 24h，点击“同步状态与统计”获取数据。'));
 else{card.append(e('p','实际采集：'+time(r.collected_at)+' · 发布后 '+((Date.parse(r.collected_at)-Date.parse(r.published_at))/3600000).toFixed(1)+' 小时累计'));const table=e('table'),tr=e('tr');for(const [key,label]of Object.entries({reach:'曝光 / 浏览¹',engagement:'互动',likes:'点赞',comments:'回复',shares:'转发 / 引用',post_clicks:'帖子点击',link_clicks:'链接点击',engagement_rate:'互动率 %'})){const td=e('td');td.append(e('div',label),e('strong',format(r.metrics[key])));tr.append(td)}table.append(tr);card.append(table,e('small','¹ Publer 的 reach 字段；X 返回帖子的浏览次数。撤回记录可能不再更新统计。'));if(r.metrics_error)card.append(e('p',r.metrics_error))}$('history-rows').append(card)}
 if(!d.rows.length)$('history-rows').append(e('p','此账号暂无工作台云端记录。新发布会自动记录；旧浏览器记录可点击上方迁移，不会混入其他渠道发布的内容。'));$('history-page').textContent=`第 ${page+1} 页 · 共 ${d.total} 条`;$('history-prev').disabled=page===0;$('history-next').disabled=(page+1)*25>=d.total;
}
async function run(fn){if(busy)return;controls(true);$('history-message').textContent='正在处理…';try{await fn();$('history-message').textContent='已更新'}catch(err){$('history-message').textContent=err.message}finally{controls(false)}}
$('tab-history').onclick=()=>{$('creation-panel').hidden=true;$('history-panel').hidden=false;run(load)};$('tab-create').onclick=()=>{$('history-panel').hidden=true;$('creation-panel').hidden=false};$('history-account').onchange=()=>{page=0;run(load)};$('history-prev').onclick=()=>{if(page>0)page--;run(load)};$('history-next').onclick=()=>{page++;run(load)};
$('history-refresh').onclick=()=>run(async()=>{const d=await api('/api/history/refresh?locale='+$('history-account').value+'&page='+page,{});await load();if(d.errors?.length)throw Error('记录已显示；'+d.errors.join('；'))});
$('history-import').onclick=()=>run(async()=>{const items=[],seen=new Set();for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key.startsWith('hotcoin-publication:'))continue;let state;try{state=JSON.parse(localStorage.getItem(key))}catch{continue}for(const [locale,r]of Object.entries(state??{})){const id=locale+':'+r.postId;if(r.postId&&!seen.has(id)){seen.add(id);items.push({locale,postId:String(r.postId)})}}}for(let i=0;i<items.length;i+=50)await api('/api/history/import',{items:items.slice(i,i+50)});await load()});
